export const ORGANIKI2_HTML: string = "<!doctype html>\n<html lang=\"el\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<meta name=\"robots\" content=\"noindex, nofollow\">\n<title>Μιχάλης Οργανική 2 · Αιθέρες & Εστέρες</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Commissioner:wght@400;500;600;700&family=JetBrains+Mono:wght@400;600&family=Literata:opsz,wght@7..72,500;7..72,700&display=swap\">\n<style>\n/* Same palette, fonts and CPK atom colours as organiki1. Layout follows the /mixalis preference:\n   full width, no boxes inside boxes, big airy figures. Orange = the acid's part, green = the alcohol's part. */\n:root{\n  --bg:#eef3f5; --card:#ffffff; --ink:#14232c; --muted:#53687a; --line:#d2dce3; --soft:#e4ecf0;\n  --accent:#0b7a6a; --accent-ink:#ffffff; --accent-soft:#d9eeea;\n  --warn:#9a5b00; --warn-soft:#fff1d1; --ok:#1b7f37; --ok-soft:#ddf2e3; --bad:#b8352a; --bad-soft:#fbe3df;\n  --atom-c:#2a3036; --atom-h:#ffffff; --atom-h-stroke:#9fb0bc; --atom-o:#e0453a; --bond:#7f8d98;\n  --acid:#d9822b; --acid-soft:#fbe6d0; --alc:#0b7a6a; --alc-soft:#d9eeea; --fat:#f1c75b; --water:#d7e9f3;\n  --f-display:\"Literata\", Georgia, \"Times New Roman\", serif;\n  --f-body:\"Commissioner\", \"Segoe UI\", system-ui, -apple-system, sans-serif;\n  --f-mono:\"JetBrains Mono\", ui-monospace, Consolas, monospace;\n  color-scheme:light;\n}\n*{box-sizing:border-box}\n[hidden]{display:none!important}\nhtml{scroll-behavior:smooth;scroll-padding-top:70px}\nbody{margin:0;background:var(--bg);color:var(--ink);font-family:var(--f-body);font-size:17px;line-height:1.62}\nbody::before{content:\"\";position:fixed;inset:0 0 auto;height:env(safe-area-inset-top,0px);z-index:30;background:var(--card)}\na{color:var(--accent)}\n:focus-visible{outline:3px solid var(--accent);outline-offset:2px;border-radius:6px}\nh1,h2,h3{text-wrap:balance;margin:0}\np{margin:0}\n.f{font-family:var(--f-mono);font-size:.95em;white-space:nowrap}\n.acid{color:var(--acid);font-weight:700}\n.alc{color:var(--alc);font-weight:700}\n.oxy{color:var(--atom-o);font-weight:700}\n\n/* header (same as organiki1) */\n.top{position:sticky;top:env(safe-area-inset-top,0px);z-index:20;background:var(--card);border-bottom:1px solid var(--line)}\n.top-in{display:flex;align-items:center;gap:18px;padding-block:10px;padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px))}\n.brand{display:flex;align-items:baseline;gap:8px;text-decoration:none;color:var(--ink);white-space:nowrap}\n.brand b{font-family:var(--f-display);font-size:20px}\n.brand span{font-family:var(--f-mono);font-size:12px;color:var(--muted)}\n.tabs{display:flex;gap:4px;overflow-x:auto;flex:1;min-width:0;scrollbar-width:none}\n.tabs::-webkit-scrollbar{display:none}\n.tabs a{white-space:nowrap;padding:7px 12px;border-radius:999px;color:var(--muted);text-decoration:none;font-weight:500;font-size:14.5px}\n.tabs a:hover{color:var(--ink);background:var(--soft)}\n.tabs a[aria-current=\"true\"]{background:var(--ink);color:var(--bg)}\n\nmain{padding-block:0 120px;padding-left:max(20px,env(safe-area-inset-left,0px));padding-right:max(20px,env(safe-area-inset-right,0px))}\n.wrap{max-width:1500px;margin:0 auto}\n.eyebrow{font-family:var(--f-mono);font-size:12.5px;letter-spacing:.09em;text-transform:uppercase;color:var(--muted)}\n.lead{max-width:72ch;font-size:19px}\n.muted{color:var(--muted)}\n\n/* hero */\n.hero{display:grid;grid-template-columns:1.1fr 1fr;gap:40px;align-items:center;min-height:min(78vh,760px);padding-block:40px}\n.hero h1{font-family:var(--f-display);font-weight:700;font-size:clamp(42px,7vw,96px);line-height:1;letter-spacing:-.02em;margin:10px 0 18px}\n.hero h1 em{font-style:normal;color:var(--acid)}\n.hero .row{margin-top:26px}\n.hero svg{width:100%;height:auto}\n@media(max-width:860px){.hero{grid-template-columns:1fr;min-height:0}}\n\n/* parts & sections: full width, separated by space and hairlines, no cards */\n.part{padding-block:70px 20px;border-top:1px solid var(--line);margin-top:60px}\n.part .big{font-family:var(--f-display);font-weight:700;font-size:clamp(80px,14vw,200px);line-height:1;letter-spacing:-.03em}\n.part.eth .big{color:var(--alc)}\n.part.est .big{color:var(--acid)}\n.part p.sub{font-size:22px;color:var(--muted);margin-top:14px}\nsub{font-size:.62em;line-height:0}\n.sec{padding-block:56px 10px;display:grid;grid-template-columns:minmax(0,1fr);gap:22px}\n.sec>*,.fig>*,.cols>*,.panel>*{min-width:0}\n.sec>h2{font-family:var(--f-display);font-weight:700;font-size:clamp(28px,3.4vw,44px);line-height:1.15}\n.sec>h2 .sn{display:inline-block;font-family:var(--f-mono);font-weight:600;font-size:15px;color:var(--accent);min-width:3.4em;vertical-align:.35em}\n.cols{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(300px,100%),1fr));gap:28px 48px}\n.cols>div{display:grid;gap:8px;align-content:start}\n.cols h3{font-size:21px}\n.lbl{font-family:var(--f-mono);font-size:12px;letter-spacing:.09em;text-transform:uppercase;font-weight:600;color:var(--muted)}\n.fig{width:100%;display:grid;grid-template-columns:minmax(0,1fr);gap:14px;justify-items:center;padding-block:10px}\n.fig svg{width:100%;height:auto;max-width:1100px}\n.fig .cap{font-size:15px;color:var(--muted);text-align:center;max-width:70ch}\n.formula{overflow-wrap:anywhere;text-align:center;font-family:var(--f-mono);font-weight:600;font-size:clamp(30px,5vw,60px);letter-spacing:.01em;line-height:1.15}\n.rule{border-left:5px solid var(--accent);padding:4px 0 4px 18px;font-size:19px;max-width:80ch}\n.rule.w{border-color:var(--warn)}\n.rule.a{border-color:var(--acid)}\n\n/* buttons & choices */\n.row{display:flex;flex-wrap:wrap;gap:10px;align-items:center}\n.btn{font:inherit;font-weight:600;font-size:16px;padding:11px 18px;border-radius:12px;border:1.5px solid var(--ink);background:var(--ink);color:var(--bg);cursor:pointer;text-decoration:none;display:inline-flex;align-items:center;gap:8px;transition:transform .12s}\n.btn:active{transform:scale(.97)}\n.btn.ghost{background:transparent;color:var(--ink);border-color:var(--line)}\n.btn.ghost:hover{border-color:var(--ink)}\n.btn.acc{background:var(--accent);border-color:var(--accent);color:var(--accent-ink)}\n.btn.or{background:var(--acid);border-color:var(--acid);color:#fff}\n.seg{display:flex;flex-wrap:wrap;gap:8px}\n.seg button{font:inherit;font-size:16px;font-weight:600;padding:9px 14px;border-radius:999px;border:1.5px solid var(--line);background:var(--card);color:var(--ink);cursor:pointer}\n.seg.ac button[aria-pressed=\"true\"]{background:var(--acid);border-color:var(--acid);color:#fff}\n.seg.al button[aria-pressed=\"true\"],.seg.dk button[aria-pressed=\"true\"]{background:var(--alc);border-color:var(--alc);color:#fff}\n\n/* reveal */\n.reveal{display:grid;gap:10px}\n.reveal .item{opacity:0;transform:translateY(10px);transition:opacity .45s,transform .45s;pointer-events:none}\n.reveal .item.on{opacity:1;transform:none;pointer-events:auto}\n.ans{color:var(--ok);font-weight:600}\n.qline{display:grid;gap:6px;padding-block:14px;border-bottom:1px solid var(--line)}\n.qline .btn{justify-self:start;font-size:14px;padding:7px 12px}\n\n/* atoms / svg */\nsvg .bond{stroke:var(--bond);stroke-width:10;stroke-linecap:round}\nsvg text{font-family:var(--f-body);font-weight:700}\n.atom{transition:fill .5s,r .5s}\n.mol-in{animation:pop .7s cubic-bezier(.2,.8,.3,1.2) both}\n@keyframes pop{0%{transform:scale(.6);opacity:0}100%{transform:scale(1);opacity:1}}\n@keyframes rise{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:none}}\n@keyframes floaty{0%,100%{transform:translateY(0)}50%{transform:translateY(-8px)}}\n.floaty{animation:floaty 5s ease-in-out infinite}\n.inview{opacity:0;transform:translateY(22px);transition:opacity .7s ease,transform .7s ease}\n.inview.seen{opacity:1;transform:none}\n\n/* boiling-point chart */\n.bp{position:relative;height:380px;max-width:640px;width:100%;margin-inline:auto}\n.bp .zero{position:absolute;left:0;right:0;top:250px;border-top:3px solid var(--ink)}\n.bp .zl{position:absolute;right:0;top:222px;font-family:var(--f-mono);font-size:13px;color:var(--muted)}\n.bp .bar{position:absolute;width:30%;border-radius:12px 12px 0 0;transition:height 1.2s cubic-bezier(.2,.7,.2,1),top 1.2s cubic-bezier(.2,.7,.2,1)}\n.bp .b1{left:8%;top:250px;height:0;background:var(--alc)}\n.bp .b2{left:58%;top:253px;height:0;background:var(--acid);border-radius:0 0 12px 12px;transition:height 1.2s .3s}\n.bp.seen .b1{top:94px;height:156px}\n.bp.seen .b2{height:48px}\n.bp .v{position:absolute;width:30%;text-align:center;font-family:var(--f-display);font-weight:700;font-size:34px;opacity:0;transition:opacity .5s 1.1s}\n.bp.seen .v{opacity:1}\n.bp .n{position:absolute;width:30%;text-align:center;font-weight:600;font-size:15px}\n\n/* reaction stage */\n.rx{display:flex;flex-wrap:wrap;gap:14px;align-items:center;justify-content:center;font-family:var(--f-mono);font-weight:600;font-size:clamp(22px,3.6vw,44px);min-height:90px}\n.tok{display:inline-block;padding:8px 14px;border-radius:12px;transition:transform .8s cubic-bezier(.4,1.3,.5,1),opacity .6s,background .4s}\n.tok.a{background:var(--acid-soft)}\n.tok.l{background:var(--alc-soft)}\n.tok.x{background:var(--soft)}\n.tok.go{background:var(--bad-soft);color:var(--bad)}\n.rx[data-step=\"1\"] .tok.go{animation:pulse .8s ease-in-out 2}\n@keyframes pulse{50%{transform:scale(1.15)}}\n.rx .op{color:var(--muted)}\n.tok.w{background:var(--water);color:#1d4f6b}\n.prod .tok,.prod .op{opacity:0;transform:translateY(-30px)}\n.prod.on .tok,.prod.on .op{opacity:1;transform:none}\n.prod.on .tok.w{transition-delay:.4s}\n.cond{font-family:var(--f-mono);font-size:15px;color:var(--acid);text-align:center;opacity:0;transition:opacity .5s}\n.cond.on{opacity:1}\n.arrow2{font-size:clamp(40px,6vw,70px);color:var(--acid);line-height:1}\n\n/* hydrolysis split */\n.split{display:grid;grid-template-columns:1fr auto 1fr;gap:24px;align-items:start}\n.split .mid{writing-mode:horizontal-tb;align-self:center;font-family:var(--f-mono);font-weight:700;font-size:clamp(24px,3vw,40px);text-align:center}\n.split .eq{font-family:var(--f-mono);font-weight:600;font-size:clamp(17px,1.8vw,22px)}\n@media(max-width:800px){.split{grid-template-columns:1fr}}\n\n/* fruits */\n.fruits{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(200px,100%),1fr));gap:30px}\n.fruits div{display:grid;gap:4px;justify-items:center;text-align:center}\n.fruits .e{font-size:84px;line-height:1.1}\n.fruits b{font-size:18px}\n\n/* traps */\nol.traps{list-style:none;margin:0;padding:0;counter-reset:t;display:grid;gap:0}\nol.traps li{counter-increment:t;display:grid;grid-template-columns:70px 1fr;gap:10px;padding-block:20px;border-bottom:1px solid var(--line);font-size:19px}\nol.traps li::before{content:counter(t);font-family:var(--f-display);font-weight:700;font-size:44px;line-height:1;color:var(--warn)}\n\n/* quiz & games */\n.games-nav{display:flex;flex-wrap:wrap;gap:10px}\n.games-nav button{font:inherit;font-weight:700;font-size:17px;padding:12px 18px;border-radius:14px;border:1.5px solid var(--line);background:var(--card);color:var(--ink);cursor:pointer}\n.games-nav button[aria-selected=\"true\"]{background:var(--ink);border-color:var(--ink);color:var(--bg)}\n.panel{display:none;animation:rise .4s ease-out}\n.panel.on{display:grid;grid-template-columns:minmax(0,1fr);gap:16px}\n.rule .f{white-space:normal}\n.meta{display:flex;justify-content:space-between;font-family:var(--f-mono);font-size:13px;color:var(--muted)}\n.pbar{height:8px;background:var(--soft);border-radius:99px;overflow:hidden}\n.pbar i{display:block;height:100%;width:0;background:var(--accent);transition:width .4s}\n.tag{font-family:var(--f-mono);font-size:12px;letter-spacing:.08em;font-weight:700;color:var(--accent)}\n.q{font-size:clamp(20px,2.2vw,26px);font-weight:600;max-width:60ch}\n.opts{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(280px,100%),1fr));gap:10px;max-width:1000px}\n.opt{display:flex;gap:12px;align-items:center;text-align:left;font:inherit;font-size:17px;font-weight:500;padding:14px 16px;border-radius:14px;border:1.5px solid var(--line);background:var(--card);color:var(--ink);cursor:pointer;transition:border-color .15s,background .15s}\n.opt:hover:not(:disabled){border-color:var(--ink)}\n.opt b{flex:none;width:30px;height:30px;border-radius:50%;display:grid;place-items:center;background:var(--soft);font-size:14px}\n.opt.ok{border-color:var(--ok);background:var(--ok-soft)}.opt.ok b{background:var(--ok);color:#fff}\n.opt.bad{border-color:var(--bad);background:var(--bad-soft)}.opt.bad b{background:var(--bad);color:#fff}\n.opt:disabled{cursor:default}\n.shake{animation:shake .35s}\n@keyframes shake{25%{transform:translateX(-6px)}75%{transform:translateX(6px)}}\n.fb{font-size:17px;max-width:80ch;padding-left:16px;border-left:5px solid var(--ok);animation:rise .3s}\n.fb.bad{border-color:var(--bad)}\n.fb strong{display:block}\n.score{font-family:var(--f-display);font-weight:700;font-size:90px;line-height:1}\n.trow{display:grid;grid-template-columns:minmax(120px,260px) 1fr 50px;gap:14px;align-items:center;max-width:900px}\n.trow .pbar i{transition:width .9s}\n.bigf{overflow-wrap:anywhere;font-family:var(--f-mono);font-weight:700;font-size:clamp(34px,6vw,64px);text-align:center;padding-block:14px}\n.cats{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:10px;max-width:1000px;margin-inline:auto;width:100%}\n.cat{font:inherit;font-weight:700;font-size:19px;padding:18px;border-radius:14px;border:1.5px solid var(--line);background:var(--card);color:var(--ink);cursor:pointer}\n.cat small{display:block;font-family:var(--f-mono);font-weight:500;font-size:13px;color:var(--muted)}\n.cat.ok{background:var(--ok-soft);border-color:var(--ok)}.cat.bad{background:var(--bad-soft);border-color:var(--bad)}\n.res{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:18px 40px}\n.res div{animation:rise .4s both}\n.res .v{font-size:22px;font-weight:700}\n\n/* study marks (shared format with the other Mixalis lessons) */\n.stmark{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin-top:8px;padding-top:12px;border-top:1px dashed var(--line)}\n.stmark span{font-family:var(--f-mono);font-size:11.5px;letter-spacing:.09em;text-transform:uppercase;font-weight:600;color:var(--muted)}\n.stmark button{font:inherit;font-size:14.5px;font-weight:600;padding:7px 14px;border-radius:999px;cursor:pointer;background:var(--card)}\n.stmark button[data-s=done]{border:1.5px solid var(--ok);color:var(--ok)}\n.stmark button[data-s=again]{border:1.5px solid var(--warn);color:var(--warn)}\n.stmark button[data-s=done][aria-pressed=true]{background:var(--ok);color:#fff}\n.stmark button[data-s=again][aria-pressed=true]{background:var(--warn);color:#fff}\n#stFab{position:fixed;right:16px;bottom:16px;z-index:40;font:inherit;font-weight:700;font-size:15px;padding:11px 16px;border-radius:999px;border:0;background:var(--ink);color:var(--card);box-shadow:0 6px 20px rgba(0,0,0,.18);cursor:pointer}\n.nextch{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-top:70px;padding-top:24px;border-top:1px solid var(--line)}\n@media (prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important}.inview{opacity:1;transform:none}html{scroll-behavior:auto}}\n</style>\n</head>\n<body>\n\n<header class=\"top\">\n  <div class=\"top-in\">\n    <a class=\"brand\" href=\"#arxi\"><b>R–O–R′</b><span>Οργανική 2</span></a>\n    <nav class=\"tabs\" id=\"tabs\" aria-label=\"Ενότητες\">\n      <a href=\"/mixalis\" title=\"Όλα τα μαθήματα\">← Μαθήματα</a>\n      <a href=\"/mixalis/organiki1\" title=\"Κεφάλαια 0–5\">Οργανική 1</a>\n      <a href=\"#arxi\" data-s=\"arxi\">Αρχή</a>\n      <a href=\"#aitheres\" data-s=\"aitheres\">Αιθέρες</a>\n      <a href=\"#esteres\" data-s=\"esteres\">Εστέρες</a>\n      <a href=\"#esteropoiisi\" data-s=\"esteropoiisi\">Εστεροποίηση</a>\n      <a href=\"#lipi\" data-s=\"lipi\">Λίπη &amp; σαπούνι</a>\n      <a href=\"#pagides\" data-s=\"pagides\">Παγίδες</a>\n      <a href=\"#kouiz\" data-s=\"kouiz\">Κουίζ &amp; παιχνίδια</a>\n    </nav>\n  </div>\n</header>\n\n<main><div class=\"wrap\">\n\n<!-- ============ HERO ============ -->\n<section class=\"hero\" id=\"arxi\">\n  <div>\n    <div class=\"eyebrow\">Χημεία Β΄ Λυκείου · §1.2–1.4, §4.1, §5.2</div>\n    <h1>Αιθέρες <em>&amp;</em> Εστέρες</h1>\n    <p class=\"lead\">Δύο οικογένειες με ένα οξυγόνο «σφηνωμένο» ανάμεσα σε άτομα άνθρακα. Θα μάθεις να τις αναγνωρίζεις, να τις ονομάζεις, να βρίσκεις τα ισομερή τους, και να φτιάχνεις εστέρες από οξύ και αλκοόλη, μέχρι και το σαπούνι.</p>\n    <p class=\"lead muted\" style=\"margin-top:12px;font-size:17px\">Σε όλη τη σελίδα το <span class=\"acid\">πορτοκαλί</span> είναι το κομμάτι που έρχεται από το οξύ, το <span class=\"alc\">πράσινο</span> από την αλκοόλη και το <span class=\"oxy\">κόκκινο</span> είναι το οξυγόνο.</p>\n    <div class=\"row\">\n      <a class=\"btn acc\" href=\"#aitheres\">Ξεκίνα →</a>\n      <a class=\"btn ghost\" href=\"#kouiz\">Πήγαινε στο κουίζ</a>\n    </div>\n  </div>\n  <svg viewBox=\"0 0 600 440\" role=\"img\" aria-label=\"Μοντέλο διμεθυλαιθέρα: κόκκινο οξυγόνο ανάμεσα σε δύο άνθρακες με τα υδρογόνα τους\">\n    <g class=\"floaty\">\n      <circle cx=\"300\" cy=\"220\" r=\"205\" fill=\"none\" stroke=\"var(--line)\" stroke-width=\"2\" stroke-dasharray=\"6 10\"/>\n      <g class=\"mol-in\">\n      <line class=\"bond\" x1=\"150\" y1=\"290\" x2=\"300\" y2=\"140\" style=\"stroke-width:14\"/>\n      <line class=\"bond\" x1=\"300\" y1=\"140\" x2=\"450\" y2=\"290\" style=\"stroke-width:14\"/>\n      <line class=\"bond\" x1=\"150\" y1=\"290\" x2=\"62\" y2=\"242\"/><line class=\"bond\" x1=\"150\" y1=\"290\" x2=\"100\" y2=\"390\"/><line class=\"bond\" x1=\"150\" y1=\"290\" x2=\"210\" y2=\"385\"/>\n      <line class=\"bond\" x1=\"450\" y1=\"290\" x2=\"538\" y2=\"242\"/><line class=\"bond\" x1=\"450\" y1=\"290\" x2=\"500\" y2=\"390\"/><line class=\"bond\" x1=\"450\" y1=\"290\" x2=\"390\" y2=\"385\"/>\n      <g fill=\"var(--atom-h)\" stroke=\"var(--atom-h-stroke)\" stroke-width=\"3\"><circle cx=\"62\" cy=\"242\" r=\"26\"/><circle cx=\"100\" cy=\"390\" r=\"26\"/><circle cx=\"210\" cy=\"385\" r=\"26\"/><circle cx=\"538\" cy=\"242\" r=\"26\"/><circle cx=\"500\" cy=\"390\" r=\"26\"/><circle cx=\"390\" cy=\"385\" r=\"26\"/></g>\n      <circle cx=\"150\" cy=\"290\" r=\"58\" fill=\"var(--atom-c)\"/><circle cx=\"450\" cy=\"290\" r=\"58\" fill=\"var(--atom-c)\"/>\n      <circle cx=\"300\" cy=\"140\" r=\"70\" fill=\"var(--atom-o)\"/>\n      <text x=\"150\" y=\"308\" text-anchor=\"middle\" font-size=\"50\" fill=\"#fff\">C</text>\n      <text x=\"450\" y=\"308\" text-anchor=\"middle\" font-size=\"50\" fill=\"#fff\">C</text>\n      <text x=\"300\" y=\"160\" text-anchor=\"middle\" font-size=\"56\" fill=\"#fff\">O</text>\n      </g>\n    </g>\n  </svg>\n</section>\n\n<!-- ============ ΑΙΘΕΡΕΣ ============ -->\n<section class=\"part eth\" id=\"aitheres\">\n  <div class=\"big\">Αιθέρες</div>\n  <p class=\"sub\">Ένα οξυγόνο ανάμεσα σε δύο αλκύλια: R–O–R′</p>\n</section>\n\n<section class=\"sec\" id=\"s-6-1\">\n  <h2><span class=\"sn\">6.1</span>Από το νερό στον αιθέρα</h2>\n  <p class=\"lead\">Ξεκίνα από το νερό, H–O–H. Πάτα το κουμπί και άλλαξε ένα-ένα τα υδρογόνα με αλκύλια.</p>\n  <div class=\"fig\">\n    <svg viewBox=\"0 0 760 330\" role=\"img\" aria-label=\"Μόριο σε σχήμα V: οξυγόνο στη μέση, και δύο άτομα ή ομάδες δεξιά και αριστερά\" id=\"wae\">\n      <line class=\"bond\" x1=\"380\" y1=\"110\" x2=\"190\" y2=\"240\" style=\"stroke-width:14\"/>\n      <line class=\"bond\" x1=\"380\" y1=\"110\" x2=\"570\" y2=\"240\" style=\"stroke-width:14\"/>\n      <circle class=\"atom\" id=\"waeL\" cx=\"190\" cy=\"240\" r=\"40\" fill=\"var(--atom-h)\" stroke=\"var(--atom-h-stroke)\" stroke-width=\"4\"/>\n      <circle class=\"atom\" id=\"waeR\" cx=\"570\" cy=\"240\" r=\"40\" fill=\"var(--atom-h)\" stroke=\"var(--atom-h-stroke)\" stroke-width=\"4\"/>\n      <circle cx=\"380\" cy=\"110\" r=\"70\" fill=\"var(--atom-o)\"/>\n      <text x=\"380\" y=\"132\" text-anchor=\"middle\" font-size=\"60\" fill=\"#fff\">O</text>\n      <text id=\"waeLt\" x=\"190\" y=\"258\" text-anchor=\"middle\" font-size=\"46\" fill=\"var(--ink)\">H</text>\n      <text id=\"waeRt\" x=\"570\" y=\"258\" text-anchor=\"middle\" font-size=\"46\" fill=\"var(--ink)\">H</text>\n    </svg>\n    <div class=\"formula\" id=\"waeF\">H–O–H</div>\n    <div class=\"lbl\" id=\"waeN\">νερό</div>\n    <div class=\"row\"><button class=\"btn acc\" id=\"waeGo\">Άλλαξε ένα H με αλκύλιο →</button><button class=\"btn ghost\" id=\"waeReset\">Από την αρχή</button></div>\n  </div>\n  <div class=\"cols\">\n    <div><span class=\"lbl\">Χαρακτηριστική ομάδα</span><h3>Αιθερομάδα –C–O–C–</h3><p>Το O ενώνει δύο άτομα C. Δεν έχει H πάνω του.</p></div>\n    <div><span class=\"lbl\">Γενικός τύπος</span><h3 class=\"f\">C<sub>ν</sub>H<sub>2ν+2</sub>O, ν ≥ 2</h3><p>Κορεσμένοι μονοαιθέρες. Χρειάζεται τουλάχιστον ένα C σε κάθε πλευρά του O.</p></div>\n    <div><span class=\"lbl\">Ο απλούστερος</span><h3 class=\"f\">CH₃–O–CH₃</h3><p>Διμεθυλαιθέρας, με ν = 2.</p></div>\n  </div>\n</section>\n\n<section class=\"sec\" id=\"s-6-2\">\n  <h2><span class=\"sn\">6.2</span>Ονοματολογία αιθέρων</h2>\n  <p class=\"lead\">Δύο τρόποι: (1) τα αλκύλια με <b>αλφαβητική σειρά</b> και μετά «αιθέρας», ή (2) κατά IUPAC το <b>μικρότερο κομμάτι μαζί με το O γίνεται αλκοξυ-</b> και το μεγαλύτερο είναι το αλκάνιο. Φτιάξε τον δικό σου αιθέρα:</p>\n  <div class=\"cols\">\n    <div><span class=\"lbl\">Αριστερά του O</span><div class=\"seg dk\" id=\"enL\"></div></div>\n    <div><span class=\"lbl\">Δεξιά του O</span><div class=\"seg dk\" id=\"enR\"></div></div>\n  </div>\n  <div class=\"fig\">\n    <div class=\"formula\" id=\"enF\"></div>\n    <div class=\"cols\" style=\"width:100%;max-width:1100px\">\n      <div><span class=\"lbl\">Τρόπος 1 · με αλκύλια</span><h3 id=\"enN1\"></h3></div>\n      <div><span class=\"lbl\">Τρόπος 2 · IUPAC</span><h3 id=\"enN2\"></h3></div>\n      <div><span class=\"lbl\">Μοριακός τύπος</span><h3 class=\"f\" id=\"enM\"></h3></div>\n    </div>\n  </div>\n  <p class=\"rule\">Αλφαβητικά: <b>α</b>ιθυλ- πριν από <b>μ</b>εθυλ- πριν από <b>π</b>ροπυλ-. Ίδια αλκύλια: δι- (διμεθυλαιθέρας).</p>\n</section>\n\n<section class=\"sec\" id=\"s-6-3\">\n  <h2><span class=\"sn\">6.3</span>Ίδιος τύπος με τις αλκοόλες, άλλος κόσμος</h2>\n  <p class=\"lead\">Αλκοόλες και αιθέρες με τον ίδιο αριθμό C έχουν τον ίδιο τύπο <span class=\"f\">C<sub>ν</sub>H<sub>2ν+2</sub>O</span>: είναι <b>ισομερή ομόλογης σειράς</b>. Δες όμως τα σημεία βρασμού του <span class=\"f\">C₂H₆O</span>:</p>\n  <div class=\"cols\" style=\"align-items:center\">\n    <div>\n      <div class=\"bp\" id=\"bp\">\n        <div class=\"lbl\" style=\"position:absolute;left:0;top:0\">Σημείο βρασμού</div>\n        <div class=\"zero\"></div><div class=\"zl\">0 °C</div>\n        <div class=\"bar b1\"></div><div class=\"bar b2\"></div>\n        <div class=\"v\" style=\"left:8%;top:40px;color:var(--alc)\">78 °C</div>\n        <div class=\"v\" style=\"left:58%;top:308px;color:var(--acid)\">−24 °C</div>\n        <div class=\"n\" style=\"left:8%;top:262px\">αιθανόλη<br><span class=\"f\">CH₃CH₂OH</span></div>\n        <div class=\"n\" style=\"left:58%;top:190px\">διμεθυλαιθέρας<br><span class=\"f\">CH₃OCH₃</span></div>\n      </div>\n    </div>\n    <div>\n      <p style=\"font-size:19px\">Ο ίδιος τύπος, αλλά η αιθανόλη είναι υγρό και ο διμεθυλαιθέρας αέριο. Πριν πατήσεις, σκέψου: <b>γιατί;</b></p>\n      <button class=\"btn acc\" id=\"hbGo\" style=\"justify-self:start;margin-top:10px\">Δείξε μου γιατί</button>\n      <div id=\"hb\" hidden style=\"margin-top:10px\">\n        <svg viewBox=\"0 0 640 150\" role=\"img\" aria-label=\"Δύο μόρια αλκοόλης ενωμένα με δεσμό υδρογόνου\" style=\"width:100%;height:auto\">\n          <line class=\"bond\" x1=\"50\" y1=\"75\" x2=\"240\" y2=\"75\"/><line class=\"bond\" x1=\"400\" y1=\"75\" x2=\"590\" y2=\"75\"/>\n          <line x1=\"265\" y1=\"75\" x2=\"375\" y2=\"75\" stroke=\"var(--alc)\" stroke-width=\"6\" stroke-dasharray=\"10 10\"><animate attributeName=\"stroke-dashoffset\" from=\"40\" to=\"0\" dur=\"1s\" repeatCount=\"indefinite\"/></line>\n          <circle cx=\"50\" cy=\"75\" r=\"38\" fill=\"var(--atom-c)\"/><circle cx=\"150\" cy=\"75\" r=\"34\" fill=\"var(--atom-o)\"/><circle cx=\"245\" cy=\"75\" r=\"22\" fill=\"var(--atom-h)\" stroke=\"var(--atom-h-stroke)\" stroke-width=\"3\"/>\n          <circle cx=\"400\" cy=\"75\" r=\"34\" fill=\"var(--atom-o)\"/><circle cx=\"495\" cy=\"75\" r=\"22\" fill=\"var(--atom-h)\" stroke=\"var(--atom-h-stroke)\" stroke-width=\"3\"/><circle cx=\"590\" cy=\"75\" r=\"38\" fill=\"var(--atom-c)\"/>\n          <text x=\"50\" y=\"90\" text-anchor=\"middle\" font-size=\"36\" fill=\"#fff\">R</text><text x=\"150\" y=\"88\" text-anchor=\"middle\" font-size=\"34\" fill=\"#fff\">O</text><text x=\"245\" y=\"83\" text-anchor=\"middle\" font-size=\"22\">H</text>\n          <text x=\"400\" y=\"88\" text-anchor=\"middle\" font-size=\"34\" fill=\"#fff\">O</text><text x=\"495\" y=\"83\" text-anchor=\"middle\" font-size=\"22\">H</text><text x=\"590\" y=\"90\" text-anchor=\"middle\" font-size=\"36\" fill=\"#fff\">R</text>\n          <text x=\"320\" y=\"130\" text-anchor=\"middle\" font-size=\"18\" fill=\"var(--alc)\">δεσμός υδρογόνου</text>\n        </svg>\n        <p style=\"font-size:18px\"><b>Δεσμοί υδρογόνου.</b> Το –OH της αλκοόλης «πιάνει» το διπλανό μόριο, οπότε χρειάζεται πολλή ενέργεια για να βράσει. Ο αιθέρας δεν έχει H πάνω στο O, άρα τα μόριά του ξεφεύγουν εύκολα.</p>\n      </div>\n    </div>\n  </div>\n</section>\n\n<section class=\"sec\" id=\"s-6-4\">\n  <h2><span class=\"sn\">6.4</span>Λυμένο: όλα τα άκυκλα ισομερή του C₄H₁₀O</h2>\n  <p class=\"lead\">Γράψε πρώτα στο τετράδιο όσα βρίσκεις. Μετά πάτα «Επόμενο» για να τα δεις ένα-ένα.</p>\n  <div class=\"cols\">\n    <div class=\"reveal\" id=\"iso4a\"><span class=\"lbl\">4 αλκοόλες</span>\n      <p class=\"item\"><span class=\"f\">CH₃CH₂CH₂CH₂OH</span> · 1-βουτανόλη</p>\n      <p class=\"item\"><span class=\"f\">CH₃CH(OH)CH₂CH₃</span> · 2-βουτανόλη</p>\n      <p class=\"item\"><span class=\"f\">(CH₃)₂CHCH₂OH</span> · 2-μεθυλο-1-προπανόλη</p>\n      <p class=\"item\"><span class=\"f\">(CH₃)₃COH</span> · 2-μεθυλο-2-προπανόλη</p>\n    </div>\n    <div class=\"reveal\" id=\"iso4b\"><span class=\"lbl\">3 αιθέρες · μοίρασε τα 4 C γύρω από το O</span>\n      <p class=\"item\"><b>1 + 3:</b> <span class=\"f\">CH₃–O–CH₂CH₂CH₃</span> · 1-μεθοξυπροπάνιο</p>\n      <p class=\"item\"><b>1 + 3:</b> <span class=\"f\">CH₃–O–CH(CH₃)₂</span> · 2-μεθοξυπροπάνιο</p>\n      <p class=\"item\"><b>2 + 2:</b> <span class=\"f\">CH₃CH₂–O–CH₂CH₃</span> · αιθοξυαιθάνιο</p>\n    </div>\n  </div>\n  <div class=\"row\"><button class=\"btn acc\" id=\"iso4Go\">Επόμενο →</button><span class=\"muted\" id=\"iso4c\">0 / 7</span></div>\n  <p class=\"rule w\">Το 3 + 1 είναι το ίδιο με το 1 + 3. Μην το μετρήσεις δύο φορές. Σύνολο: <b>7 ισομερή</b>.</p>\n</section>\n\n<section class=\"sec\" id=\"s-6-5\">\n  <h2><span class=\"sn\">6.5</span>Ο πιο γνωστός: ο διαιθυλαιθέρας</h2>\n  <div class=\"formula\">CH₃CH₂–O–CH₂CH₃</div>\n  <div class=\"cols\">\n    <div><span class=\"lbl\">Ιστορία</span><h3>Πρώτο αναισθητικό</h3><p>Από το 1846 χρησιμοποιήθηκε στα χειρουργεία για νάρκωση. Σήμερα έχει αντικατασταθεί από ασφαλέστερα φάρμακα.</p></div>\n    <div><span class=\"lbl\">Ιδιότητες</span><h3>Πτητικός, εύφλεκτος</h3><p>Βράζει στους 35 °C και εξατμίζεται αμέσως. Οι ατμοί του αναφλέγονται πολύ εύκολα.</p></div>\n    <div><span class=\"lbl\">Χρήση</span><h3>Διαλύτης</h3><p>Διαλύει λίπη και πολλές οργανικές ενώσεις. Είναι σχετικά αδρανής. Μην τον μπερδέψεις με τα «αιθέρια έλαια» των αρωμάτων.</p></div>\n  </div>\n</section>\n\n<section class=\"sec\" id=\"s-6-6\">\n  <h2><span class=\"sn\">6.6</span>Γρήγορος έλεγχος πριν τους εστέρες</h2>\n  <div class=\"qline\"><p>1. Ποιο από τα δύο είναι αιθέρας: <span class=\"f\">CH₃CH₂OH</span> ή <span class=\"f\">CH₃OCH₃</span>;</p><button class=\"btn ghost\" data-rev>Απάντηση</button><p class=\"ans\" hidden>CH₃OCH₃: το O είναι ανάμεσα σε δύο C.</p></div>\n  <div class=\"qline\"><p>2. Ονόμασε κατά IUPAC το <span class=\"f\">CH₃–O–CH₂CH₂CH₃</span>.</p><button class=\"btn ghost\" data-rev>Απάντηση</button><p class=\"ans\" hidden>1-μεθοξυπροπάνιο (μεθυλοπροπυλαιθέρας)</p></div>\n  <div class=\"qline\"><p>3. Πόσες αλκοόλες και πόσους αιθέρες δίνει το <span class=\"f\">C₃H₈O</span>;</p><button class=\"btn ghost\" data-rev>Απάντηση</button><p class=\"ans\" hidden>2 αλκοόλες (1- και 2-προπανόλη) και 1 αιθέρα (μεθοξυαιθάνιο).</p></div>\n</section>\n\n<!-- ============ ΕΣΤΕΡΕΣ ============ -->\n<section class=\"part est\" id=\"esteres\">\n  <div class=\"big\">Εστέρες</div>\n  <p class=\"sub\">Οξύ + αλκοόλη: η χημεία πίσω από τα αρώματα των φρούτων</p>\n</section>\n\n<section class=\"sec\" id=\"s-7-1\">\n  <h2><span class=\"sn\">7.1</span>Από το οξύ στον εστέρα</h2>\n  <p class=\"lead\">Πάρε ένα καρβοξυλικό οξύ, <span class=\"f\">R–COOH</span>. Αν το H του –COOH αντικατασταθεί από αλκύλιο <span class=\"alc\">R′</span>, έχεις εστέρα.</p>\n  <div class=\"fig\">\n    <svg viewBox=\"0 0 760 300\" role=\"img\" aria-label=\"Καρβοξυλικό οξύ που γίνεται εστέρας: το H στο δεξί άκρο αντικαθίσταται από αλκύλιο R′\" id=\"ae\">\n      <line class=\"bond\" x1=\"110\" y1=\"200\" x2=\"300\" y2=\"200\" style=\"stroke-width:12\"/>\n      <line class=\"bond\" x1=\"292\" y1=\"200\" x2=\"292\" y2=\"75\"/><line class=\"bond\" x1=\"308\" y1=\"200\" x2=\"308\" y2=\"75\"/>\n      <line class=\"bond\" x1=\"300\" y1=\"200\" x2=\"470\" y2=\"200\" style=\"stroke-width:12\"/>\n      <line class=\"bond\" x1=\"470\" y1=\"200\" x2=\"620\" y2=\"200\" style=\"stroke-width:12\"/>\n      <circle cx=\"110\" cy=\"200\" r=\"58\" fill=\"var(--acid)\"/>\n      <circle cx=\"300\" cy=\"200\" r=\"44\" fill=\"var(--atom-c)\"/>\n      <circle cx=\"300\" cy=\"70\" r=\"42\" fill=\"var(--atom-o)\"/>\n      <circle cx=\"470\" cy=\"200\" r=\"42\" fill=\"var(--atom-o)\"/>\n      <circle class=\"atom\" id=\"aeX\" cx=\"625\" cy=\"200\" r=\"34\" fill=\"var(--atom-h)\" stroke=\"var(--atom-h-stroke)\" stroke-width=\"4\"/>\n      <text x=\"110\" y=\"218\" text-anchor=\"middle\" font-size=\"50\" fill=\"#fff\">R</text>\n      <text x=\"300\" y=\"216\" text-anchor=\"middle\" font-size=\"44\" fill=\"#fff\">C</text>\n      <text x=\"300\" y=\"86\" text-anchor=\"middle\" font-size=\"44\" fill=\"#fff\">O</text>\n      <text x=\"470\" y=\"216\" text-anchor=\"middle\" font-size=\"44\" fill=\"#fff\">O</text>\n      <text id=\"aeXt\" x=\"625\" y=\"216\" text-anchor=\"middle\" font-size=\"42\" fill=\"var(--ink)\">H</text>\n    </svg>\n    <div class=\"formula\" id=\"aeF\"><span class=\"acid\">R</span>–COO<span>H</span></div>\n    <div class=\"lbl\" id=\"aeN\">καρβοξυλικό οξύ</div>\n    <div class=\"row\"><button class=\"btn or\" id=\"aeGo\">Κάν' το εστέρα →</button></div>\n  </div>\n  <div class=\"cols\">\n    <div><span class=\"lbl\">Χαρακτηριστική ομάδα</span><h3>Εστερομάδα –COO–</h3><p>Το <span class=\"acid\">R</span> έρχεται από το οξύ (μπορεί να είναι και H), το <span class=\"alc\">R′</span> από την αλκοόλη.</p></div>\n    <div><span class=\"lbl\">Γενικός τύπος</span><h3 class=\"f\">C<sub>ν</sub>H<sub>2ν</sub>O<sub>2</sub>, ν ≥ 2</h3><p>Εστέρες κορεσμένων μονοκαρβοξυλικών οξέων με κορεσμένες μονοσθενείς αλκοόλες.</p></div>\n    <div><span class=\"lbl\">Ο απλούστερος</span><h3 class=\"f\">HCOOCH₃</h3><p>Μεθανικός μεθυλεστέρας, με ν = 2.</p></div>\n  </div>\n</section>\n\n<section class=\"sec\" id=\"s-7-2\">\n  <h2><span class=\"sn\">7.2</span>Ονοματολογία: κόψε τον τύπο στο –COO–</h2>\n  <p class=\"lead\">Το κομμάτι που περιέχει τον C του –COO– δίνει το <span class=\"acid\">οξύ σε -ικός</span>. Το αλκύλιο μετά το O δίνει το <span class=\"alc\">…εστέρας</span>. Διάλεξε έναν εστέρα και μάντεψε το όνομα πριν το δεις:</p>\n  <div class=\"seg dk\" id=\"esPick\"></div>\n  <div class=\"fig\">\n    <div class=\"formula\" id=\"esF\"></div>\n    <button class=\"btn ghost\" id=\"esShow\">Δείξε το όνομα</button>\n    <div class=\"formula\" id=\"esN\" style=\"font-family:var(--f-display);font-size:clamp(26px,4vw,48px)\" hidden></div>\n    <div class=\"cap\" id=\"esW\" hidden></div>\n  </div>\n</section>\n\n<section class=\"sec\" id=\"esteropoiisi\">\n  <h2><span class=\"sn\">7.3</span>Εστεροποίηση: οξύ + αλκοόλη</h2>\n  <p class=\"lead\">Δες τα κόκκινα κομμάτια: το <b>OH φεύγει από το οξύ</b> και το <b>H από την αλκοόλη</b>. Μαζί κάνουν ένα μόριο νερού. Πάτα «Τρέξε την αντίδραση».</p>\n  <div class=\"fig\">\n    <div class=\"rx\" id=\"rx\" data-step=\"0\">\n      <span class=\"tok a\">CH₃CO</span><span class=\"tok go\">OH</span><span class=\"op\">+</span><span class=\"tok go\">H</span><span class=\"tok l\">OCH₂CH₃</span>\n    </div>\n    <div class=\"cap\">αιθανικό οξύ + αιθανόλη</div>\n    <div class=\"cond\" id=\"rxc\"><div class=\"arrow2\">⇌</div>πυκνό H₂SO₄ · θέρμανση · αμφίδρομη</div>\n    <div class=\"rx prod\" id=\"rxp\">\n      <span class=\"tok a\">CH₃COO</span><span class=\"tok l\" style=\"margin-left:-14px\">CH₂CH₃</span><span class=\"op\">+</span><span class=\"tok w\">H₂O</span>\n    </div>\n    <div class=\"cap cond\" id=\"rxn\">αιθανικός αιθυλεστέρας + νερό</div>\n    <div class=\"row\"><button class=\"btn or\" id=\"rxGo\">▶ Τρέξε την αντίδραση</button><a class=\"btn ghost\" href=\"#kouiz\" data-game=\"build\">Φτιάξε δικό σου εστέρα →</a></div>\n  </div>\n  <p class=\"rule a\">Γενικά: <span class=\"f\">RCOOH + R′OH ⇌ RCOOR′ + H₂O</span>. Πάντα <b>διπλό βέλος ⇌</b>, γιατί καταλήγει σε χημική ισορροπία. Καταλύτης: πυκνό H₂SO₄.</p>\n</section>\n\n<section class=\"sec\" id=\"s-7-4\">\n  <h2><span class=\"sn\">7.4</span>Υδρόλυση: η εστεροποίηση ανάποδα</h2>\n  <div class=\"split\">\n    <div style=\"display:grid;gap:8px\"><span class=\"lbl\">Όξινη υδρόλυση (H⁺)</span><p class=\"eq\">RCOOR′ + H₂O ⇌ RCOOH + R′OH</p><p>Δίνει πίσω <b>οξύ + αλκοόλη</b>. <b>Αμφίδρομη</b>, όπως η εστεροποίηση.</p></div>\n    <div class=\"mid\"><span class=\"acid\">RCOO</span><span class=\"alc\">R′</span></div>\n    <div style=\"display:grid;gap:8px\"><span class=\"lbl\" style=\"color:var(--acid)\">Με NaOH · σαπωνοποίηση</span><p class=\"eq\">RCOOR′ + NaOH → RCOONa + R′OH</p><p>Δίνει <b>άλας + αλκοόλη</b>. <b>Μονόδρομη</b> →, πάει μέχρι το τέλος.</p></div>\n  </div>\n  <p class=\"rule a\">Παράδειγμα: <span class=\"f\">CH₃COOCH₂CH₃ + NaOH → CH₃COONa + CH₃CH₂OH</span></p>\n</section>\n\n<section class=\"sec\" id=\"s-7-5\">\n  <h2><span class=\"sn\">7.5</span>Οξέα και εστέρες: ίδιος τύπος C<sub>ν</sub>H<sub>2ν</sub>O<sub>2</sub></h2>\n  <p class=\"lead\">Βρες όλα τα άκυκλα ισομερή του <span class=\"f\">C₃H₆O₂</span> με ομάδα –COO–. Πόσα βρίσκεις πριν πατήσεις;</p>\n  <div class=\"cols reveal\" id=\"iso3\">\n    <div class=\"item\"><span class=\"lbl\">Οξύ</span><p class=\"formula\" style=\"font-size:clamp(24px,3vw,36px)\"><span class=\"acid\">CH₃CH₂COOH</span></p><h3>προπανικό οξύ</h3></div>\n    <div class=\"item\"><span class=\"lbl\">Εστέρας · 2 + 1</span><p class=\"formula\" style=\"font-size:clamp(24px,3vw,36px)\"><span class=\"acid\">CH₃COO</span><span class=\"alc\">CH₃</span></p><h3>αιθανικός μεθυλεστέρας</h3></div>\n    <div class=\"item\"><span class=\"lbl\">Εστέρας · 1 + 2</span><p class=\"formula\" style=\"font-size:clamp(24px,3vw,36px)\"><span class=\"acid\">HCOO</span><span class=\"alc\">CH₂CH₃</span></p><h3>μεθανικός αιθυλεστέρας</h3></div>\n  </div>\n  <div class=\"row\"><button class=\"btn or\" id=\"iso3Go\">Επόμενο →</button><span class=\"muted\" id=\"iso3c\">0 / 3</span></div>\n</section>\n\n<section class=\"sec\" id=\"s-7-6\">\n  <h2><span class=\"sn\">7.6</span>Γιατί η μπανάνα μυρίζει μπανάνα</h2>\n  <p class=\"lead\">Οι μικροί εστέρες είναι πτητικοί και έχουν ευχάριστη, φρουτώδη οσμή. Χρησιμοποιούνται ως αρωματικές ύλες σε τρόφιμα, γλυκά και καλλυντικά, και ως διαλύτες.</p>\n  <div class=\"fruits\">\n    <div class=\"inview\"><span class=\"e\">🍌</span><b>αιθανικός πεντυλεστέρας</b><span class=\"f muted\">CH₃COO(CH₂)₄CH₃</span></div>\n    <div class=\"inview\"><span class=\"e\">🍍</span><b>βουτανικός αιθυλεστέρας</b><span class=\"f muted\">CH₃CH₂CH₂COOCH₂CH₃</span></div>\n    <div class=\"inview\"><span class=\"e\">🍊</span><b>αιθανικός οκτυλεστέρας</b><span class=\"f muted\">CH₃COO(CH₂)₇CH₃</span></div>\n    <div class=\"inview\"><span class=\"e\">💅</span><b>αιθανικός αιθυλεστέρας</b><span class=\"f muted\">διαλύτης στο ασετόν νυχιών</span></div>\n  </div>\n</section>\n\n<!-- ============ ΛΙΠΗ ============ -->\n<section class=\"part est\" id=\"lipi\">\n  <div class=\"big\">Λίπη &amp; σαπούνι</div>\n  <p class=\"sub\">§5.2 · Μεγάλοι εστέρες που τρώμε, και πώς γίνονται σαπούνι</p>\n</section>\n\n<section class=\"sec\" id=\"s-8-1\">\n  <h2><span class=\"sn\">8.1</span>Τα λίπη είναι κι αυτά εστέρες</h2>\n  <p class=\"lead\">Είναι εστέρες της <span class=\"alc\">γλυκερίνης</span> (τρισθενής αλκοόλη, με 3 –OH: 1,2,3-προπανοτριόλη) με 3 <span class=\"acid\">ανώτερα λιπαρά οξέα</span>. Γι' αυτό λέγονται <b>τριγλυκερίδια</b>.</p>\n  <div class=\"seg dk\" id=\"fatPick\"><button aria-pressed=\"true\" data-k=\"sat\">🧈 Λίπος (κορεσμένο)</button><button aria-pressed=\"false\" data-k=\"uns\">🫒 Έλαιο (ακόρεστο)</button></div>\n  <div class=\"fig\">\n    <svg viewBox=\"0 0 900 520\" role=\"img\" aria-label=\"Τριγλυκερίδιο: σκελετός γλυκερίνης αριστερά, ενωμένος μέσω τριών εστερικών ομάδων με τρεις αλυσίδες λιπαρών οξέων\" id=\"tg\">\n      <line x1=\"90\" y1=\"100\" x2=\"90\" y2=\"380\" stroke=\"var(--alc)\" stroke-width=\"16\" stroke-linecap=\"round\"/>\n      <g id=\"tgRows\"></g>\n      <text x=\"90\" y=\"460\" text-anchor=\"middle\" font-size=\"22\" fill=\"var(--alc)\">γλυκερίνη</text>\n      <text x=\"560\" y=\"40\" text-anchor=\"middle\" font-size=\"22\" fill=\"var(--acid)\">3 λιπαρά οξέα</text>\n      <text id=\"tgNote\" x=\"400\" y=\"490\" text-anchor=\"middle\" font-size=\"20\" fill=\"var(--ink)\" opacity=\"0\">διπλός δεσμός: η αλυσίδα «λυγίζει»</text>\n    </svg>\n  </div>\n  <div class=\"cols\">\n    <div><span class=\"lbl\">🧈 Λίπη · στερεά</span><p>Κυρίως <b>κορεσμένα</b> λιπαρά οξέα με ίσιες αλυσίδες, που «στοιβάζονται» εύκολα η μία δίπλα στην άλλη. Συνήθως ζωικά, π.χ. βούτυρο.</p></div>\n    <div><span class=\"lbl\">🫒 Έλαια · υγρά</span><p>Κυρίως <b>ακόρεστα</b>: οι διπλοί δεσμοί λυγίζουν τις αλυσίδες και δεν στοιβάζονται. Συνήθως φυτικά, π.χ. ελαιόλαδο.</p></div>\n  </div>\n</section>\n\n<section class=\"sec\" id=\"s-8-2\">\n  <h2><span class=\"sn\">8.2</span>Από το λάδι στο σαπούνι</h2>\n  <div class=\"formula\" style=\"font-size:clamp(20px,3vw,38px)\">λίπος + 3 NaOH → 3 σαπούνι + γλυκερίνη</div>\n  <div class=\"cols\" style=\"align-items:center\">\n    <div style=\"gap:18px\">\n      <p style=\"font-size:19px\">Το σαπούνι είναι <b>άλας λιπαρού οξέος</b>, π.χ. στεατικό νάτριο <span class=\"f\">C₁₇H₃₅COONa</span>. Φτιάχνεται με <b>σαπωνοποίηση</b> τριγλυκεριδίου.</p>\n      <p style=\"font-size:19px\">Με <b>NaOH</b> βγαίνουν στερεά σαπούνια, με <b>KOH</b> μαλακά και υγρά.</p>\n      <p style=\"font-size:19px\">Κάθε μόριο έχει μια <span class=\"alc\">κεφαλή –COO⁻</span> που «αγαπά» το νερό και μια μακριά <span class=\"acid\">ουρά</span> που «αγαπά» το λίπος. Ρίξε σαπούνι στη σταγόνα και δες τι γίνεται.</p>\n      <div class=\"row\"><button class=\"btn acc\" id=\"micGo\">🧼 Ρίξε σαπούνι</button><button class=\"btn ghost\" id=\"micReset\">Ξανά</button></div>\n    </div>\n    <div class=\"fig\">\n      <svg viewBox=\"0 0 520 520\" role=\"img\" aria-label=\"Μικκύλιο: μόρια σαπουνιού γύρω από σταγόνα λίπους, με τις ουρές στο λίπος και τις κεφαλές στο νερό\" id=\"mic\" style=\"max-width:560px\">\n        <circle cx=\"260\" cy=\"260\" r=\"255\" fill=\"var(--water)\"/>\n        <circle cx=\"260\" cy=\"260\" r=\"90\" fill=\"var(--fat)\"/>\n        <text x=\"260\" y=\"268\" text-anchor=\"middle\" font-size=\"24\" fill=\"#5b4300\">λίπος</text>\n        <text x=\"40\" y=\"40\" font-size=\"20\" fill=\"#1d4f6b\">νερό</text>\n        <g id=\"micMols\"></g>\n      </svg>\n      <div class=\"cap\" id=\"micCap\">Τα μόρια του σαπουνιού κολυμπάνε σκόρπια στο νερό.</div>\n    </div>\n  </div>\n</section>\n\n<!-- ============ ΠΑΓΙΔΕΣ ============ -->\n<section class=\"sec\" id=\"pagides\">\n  <h2><span class=\"sn\">9</span>Πέντε παγίδες στα διαγωνίσματα</h2>\n  <ol class=\"traps\">\n    <li><span><b>Όνομα εστέρα:</b> πρώτα το οξύ (-ικός), μετά το αλκύλιο (-εστέρας). Όχι «αιθυλικός αιθανεστέρας».</span></li>\n    <li><span><b>Ο C του –COO–</b> μετράει στο οξύ: το <span class=\"f\">CH₃COO–</span> έχει 2 C, άρα αιθανικός.</span></li>\n    <li><span><b>Εστεροποίηση:</b> πάντα ⇌, γιατί είναι αμφίδρομη.</span></li>\n    <li><span><b>Σαπωνοποίηση:</b> με NaOH πάει μέχρι το τέλος, γράφεις →.</span></li>\n    <li><span><b>Ισομερή αιθέρων:</b> το 1 + 3 είναι ίδιο με το 3 + 1. Μην το μετράς δύο φορές.</span></li>\n  </ol>\n</section>\n\n<!-- ============ ΚΟΥΙΖ ============ -->\n<section class=\"sec\" id=\"kouiz\">\n  <h2><span class=\"sn\">10</span>Κουίζ &amp; παιχνίδια επανάληψης</h2>\n  <p class=\"lead\">Δες τι θυμάσαι και τι κατάλαβες. Κάθε λάθος σού δείχνει σε ποια ενότητα να γυρίσεις.</p>\n  <div class=\"games-nav\" role=\"tablist\">\n    <button role=\"tab\" aria-selected=\"true\" data-p=\"quiz\">🧠 Κουίζ 15 ερωτήσεων</button>\n    <button role=\"tab\" aria-selected=\"false\" data-p=\"sort\">⚡ Ταξινόμησε</button>\n    <button role=\"tab\" aria-selected=\"false\" data-p=\"build\">🧪 Φτιάξε εστέρα</button>\n  </div>\n\n  <div class=\"panel on\" id=\"p-quiz\">\n    <div class=\"meta\"><span id=\"qnum\"></span><span id=\"qscore\"></span></div>\n    <div class=\"pbar\"><i id=\"qbar\"></i></div>\n    <div id=\"qbody\" style=\"display:grid;grid-template-columns:minmax(0,1fr);gap:16px\"></div>\n    <div id=\"qfb\"></div>\n    <div class=\"row\"><button class=\"btn acc\" id=\"qnext\" hidden>Επόμενη →</button></div>\n  </div>\n\n  <div class=\"panel\" id=\"p-sort\">\n    <div class=\"meta\"><span id=\"snum\"></span><span>Σερί: <b id=\"sstreak\">0</b> · Ρεκόρ: <b id=\"sbest\">0</b></span></div>\n    <div class=\"pbar\"><i id=\"sbar\"></i></div>\n    <p class=\"muted\" style=\"text-align:center\">Σε ποια ομόλογη σειρά ανήκει;</p>\n    <div class=\"bigf\" id=\"sform\"></div>\n    <div class=\"cats\" id=\"scats\"></div>\n    <div id=\"sfb\" style=\"justify-self:center\"></div>\n    <div class=\"row\" style=\"justify-content:center\"><button class=\"btn acc\" id=\"snext\" hidden>Επόμενο →</button></div>\n    <p class=\"muted\" style=\"text-align:center;font-size:15px\">Κόλπο: κοίτα γύρω από το O. Στο τέλος –OH: αλκοόλη. O ανάμεσα σε δύο C: αιθέρας. –COOH: οξύ. –COO– ανάμεσα σε C: εστέρας.</p>\n  </div>\n\n  <div class=\"panel\" id=\"p-build\">\n    <div class=\"cols\">\n      <div><span class=\"lbl\">1 · Διάλεξε οξύ</span><div class=\"seg ac\" id=\"bAcid\"></div></div>\n      <div><span class=\"lbl\">2 · Διάλεξε αλκοόλη</span><div class=\"seg al\" id=\"bAlc\"></div></div>\n    </div>\n    <div id=\"bGuess\" style=\"display:grid;grid-template-columns:minmax(0,1fr);gap:10px\"></div>\n    <div class=\"rx\" id=\"bEq\" style=\"font-size:clamp(18px,2.6vw,32px)\"><span class=\"muted\" style=\"font-family:var(--f-body);font-weight:500;font-size:18px\">Διάλεξε ένα οξύ και μία αλκοόλη 👆</span></div>\n    <div class=\"res\" id=\"bRes\"></div>\n  </div>\n</section>\n\n<div class=\"nextch\">\n  <a class=\"btn ghost\" href=\"/mixalis/organiki1\">← Οργανική 1 (κεφ. 0–5)</a>\n  <a class=\"btn ghost\" href=\"/mixalis\">Όλα τα μαθήματα</a>\n</div>\n\n</div></main>\n\n<script>\n(function(){\n\"use strict\";\nconst $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>Array.from(r.querySelectorAll(s));\nconst shuffle=a=>{a=a.slice();for(let i=a.length-1;i>0;i--){const j=Math.random()*(i+1)|0;[a[i],a[j]]=[a[j],a[i]];}return a;};\nconst sub=n=>String(n).replace(/\\d/g,d=>'₀₁₂₃₄₅₆₇₈₉'[d]);\nconst store={get(k,d){try{const v=localStorage.getItem(k);return v==null?d:JSON.parse(v);}catch(e){return d;}},set(k,v){try{localStorage.setItem(k,JSON.stringify(v));}catch(e){}}};\nconst NS='http://www.w3.org/2000/svg';\nconst el=(tag,attrs)=>{const e=document.createElementNS(NS,tag);for(const k in attrs)e.setAttribute(k,attrs[k]);return e;};\n\n/* ---------- scroll spy + in-view ---------- */\nconst tabs=$$('#tabs a[data-s]');\nconst spyTargets=tabs.map(a=>document.getElementById(a.dataset.s)).filter(Boolean);\nfunction spy(){let cur=spyTargets[0];for(const t of spyTargets){if(t.getBoundingClientRect().top<140)cur=t;}\n tabs.forEach(a=>a.setAttribute('aria-current',a.dataset.s===cur.id));}\naddEventListener('scroll',spy,{passive:true});spy();\nconst io=('IntersectionObserver' in window)?new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('seen');io.unobserve(e.target);}}),{threshold:.35}):null;\n$$('.inview,#bp').forEach(x=>io?io.observe(x):x.classList.add('seen'));\n\n/* ---------- 6.1 water → alcohol → ether ---------- */\n(function(){\n const S=[{l:'H',r:'H',f:'H–O–H',n:'νερό'},{l:'R',r:'H',f:'R–O–H',n:'αλκοόλη'},{l:'R',r:'R′',f:'R–O–R′',n:'αιθέρας'}];\n let i=0;const L=$('#waeL'),R=$('#waeR'),Lt=$('#waeLt'),Rt=$('#waeRt'),go=$('#waeGo');\n function set(atom,txt,isR){atom.setAttribute('fill',isR?'var(--alc)':'var(--atom-h)');atom.setAttribute('r',isR?58:40);atom.setAttribute('stroke',isR?'none':'var(--atom-h-stroke)');txt.textContent=isR?(txt===Rt?'R′':'R'):'H';txt.setAttribute('fill',isR?'#fff':'var(--ink)');}\n function paint(){const s=S[i];set(L,Lt,s.l!=='H');set(R,Rt,s.r!=='H');$('#waeF').textContent=s.f;$('#waeN').textContent=s.n;\n  $('#waeF').style.animation='none';void $('#waeF').offsetWidth;$('#waeF').style.animation='rise .5s';\n  go.textContent=i===0?'Άλλαξε ένα H με αλκύλιο →':i===1?'Άλλαξε και το άλλο H →':'✓ Αυτός είναι αιθέρας';go.disabled=i===2;}\n go.onclick=()=>{if(i<2){i++;paint();}};$('#waeReset').onclick=()=>{i=0;paint();};paint();\n})();\n\n/* ---------- 6.2 ether namer ---------- */\n(function(){\n const LBL=['μεθύλιο','αιθύλιο','προπύλιο'];\n const A=[{p:'μεθυλ',ox:'μεθοξυ',al:'μεθάνιο',l:'CH₃',r:'CH₃',c:1},{p:'αιθυλ',ox:'αιθοξυ',al:'αιθάνιο',l:'CH₃CH₂',r:'CH₂CH₃',c:2},{p:'προπυλ',ox:'προποξυ',al:'προπάνιο',l:'CH₃CH₂CH₂',r:'CH₂CH₂CH₃',c:3}];\n let a=0,b=1;\n function seg(id,get,setter){const host=$(id);host.innerHTML=A.map((x,i)=>'<button data-i=\"'+i+'\">'+LBL[i]+'</button>').join('');\n  $$('button',host).forEach(btn=>btn.onclick=()=>{setter(+btn.dataset.i);paint();});}\n seg('#enL',()=>a,v=>a=v);seg('#enR',()=>b,v=>b=v);\n function paint(){\n  $$('#enL button').forEach((x,i)=>x.setAttribute('aria-pressed',i===a));$$('#enR button').forEach((x,i)=>x.setAttribute('aria-pressed',i===b));\n  const L=A[a],R=A[b];\n  $('#enF').innerHTML='<span class=\"alc\">'+L.l+'</span>–<span class=\"oxy\">O</span>–<span class=\"alc\">'+R.r+'</span>';\n  let n1;if(a===b)n1='δι'+L.p+'αιθέρας';else{const s=[L,R].sort((x,y)=>x.p.localeCompare(y.p,'el'));n1=s[0].p+'ο'+s[1].p+'αιθέρας';}\n  const small=L.c<=R.c?L:R,big=L.c<=R.c?R:L;const n2=(big.c===3?'1-':'')+small.ox+big.al;\n  $('#enN1').textContent=n1;$('#enN2').textContent=n2;const n=L.c+R.c;$('#enM').textContent='C'+sub(n)+'H'+sub(2*n+2)+'O';\n  ['#enF','#enN1','#enN2'].forEach(s=>{const e=$(s);e.style.animation='none';void e.offsetWidth;e.style.animation='rise .4s';});}\n paint();\n})();\n\n/* ---------- 6.3 H-bond reveal ---------- */\n$('#hbGo').onclick=()=>{$('#hb').hidden=false;$('#hb').style.animation='rise .5s';$('#hbGo').hidden=true;};\n\n/* ---------- step reveals ---------- */\nfunction stepper(btn,count,hosts,label){let k=0;const items=hosts.flatMap(h=>$$('.item',h));const total=items.length;\n btn.onclick=()=>{if(k<total){items[k].classList.add('on');k++;}label.textContent=k+' / '+total;if(k===total){btn.textContent='Ξανά από την αρχή ↺';btn.onclick=()=>{items.forEach(x=>x.classList.remove('on'));k=0;label.textContent='0 / '+total;btn.textContent='Επόμενο →';stepper(btn,count,hosts,label);};}};}\nstepper($('#iso4Go'),7,[$('#iso4a'),$('#iso4b')],$('#iso4c'));\nstepper($('#iso3Go'),3,[$('#iso3')],$('#iso3c'));\n$$('[data-rev]').forEach(b=>b.onclick=()=>{const a=b.nextElementSibling;a.hidden=false;a.style.animation='rise .4s';b.hidden=true;});\n\n/* ---------- 7.1 acid → ester ---------- */\n(function(){let done=false;const go=$('#aeGo');\n go.onclick=()=>{done=!done;const X=$('#aeX'),T=$('#aeXt');\n  X.setAttribute('fill',done?'var(--alc)':'var(--atom-h)');X.setAttribute('r',done?58:34);X.setAttribute('stroke',done?'none':'var(--atom-h-stroke)');\n  T.textContent=done?'R′':'H';T.setAttribute('fill',done?'#fff':'var(--ink)');T.setAttribute('font-size',done?50:42);\n  $('#aeF').innerHTML=done?'<span class=\"acid\">R</span>–COO–<span class=\"alc\">R′</span>':'<span class=\"acid\">R</span>–COO<span>H</span>';\n  $('#aeN').textContent=done?'εστέρας':'καρβοξυλικό οξύ';go.textContent=done?'← Πίσω στο οξύ':'Κάν’ το εστέρα →';\n  const f=$('#aeF');f.style.animation='none';void f.offsetWidth;f.style.animation='rise .5s';};\n})();\n\n/* ---------- 7.2 ester naming ---------- */\n(function(){\n const E=[{a:'HCOO',l:'CH₃',n1:'μεθανικός',n2:'μεθυλ',w:'Το HCOO– έχει 1 C (από το μεθανικό οξύ HCOOH).'},\n  {a:'CH₃COO',l:'CH₂CH₃',n1:'αιθανικός',n2:'αιθυλ',w:'Το CH₃COO– έχει 2 C: αιθανικό οξύ. Λέγεται και οξικός αιθυλεστέρας.'},\n  {a:'CH₃CH₂COO',l:'CH₃',n1:'προπανικός',n2:'μεθυλ',w:'Το CH₃CH₂COO– έχει 3 C, μαζί με τον C του –COO–: προπανικό οξύ.'},\n  {a:'HCOO',l:'CH₂CH₃',n1:'μεθανικός',n2:'αιθυλ',w:'Ίδιος μοριακός τύπος με τον αιθανικό μεθυλεστέρα (C₃H₆O₂), αλλά άλλη ένωση!'},\n  {a:'CH₃CH₂CH₂COO',l:'CH₂CH₃',n1:'βουτανικός',n2:'αιθυλ',w:'4 C στο κομμάτι του οξέος: βουτανικό. Μυρίζει ανανά! 🍍'}];\n const host=$('#esPick');host.innerHTML=E.map((e,i)=>'<button data-i=\"'+i+'\">'+e.a+e.l+'</button>').join('');\n let cur=0;function paint(){$$('button',host).forEach((b,i)=>b.setAttribute('aria-pressed',i===cur));const e=E[cur];\n  $('#esF').innerHTML='<span class=\"acid\">'+e.a+'</span><span class=\"muted\">|</span><span class=\"alc\">'+e.l+'</span>';\n  $('#esN').innerHTML='<span class=\"acid\">'+e.n1+'</span> <span class=\"alc\">'+e.n2+'</span>εστέρας';$('#esW').textContent=e.w;\n  $('#esN').hidden=true;$('#esW').hidden=true;$('#esShow').hidden=false;}\n $$('button',host).forEach(b=>b.onclick=()=>{cur=+b.dataset.i;paint();});\n $('#esShow').onclick=()=>{$('#esN').hidden=false;$('#esW').hidden=false;$('#esN').style.animation='rise .4s';$('#esShow').hidden=true;};\n paint();\n})();\n\n/* ---------- 7.3 esterification run ---------- */\n(function(){const rx=$('#rx'),p=$('#rxp'),c=$('#rxc'),n=$('#rxn'),go=$('#rxGo');let t=[];\n function reset(){t.forEach(clearTimeout);t=[];rx.dataset.step='0';p.classList.remove('on');c.classList.remove('on');n.classList.remove('on');$$('.tok.go',rx).forEach(x=>{x.style.opacity='';x.style.transform='';});}\n go.onclick=()=>{reset();rx.dataset.step='1';go.textContent='↺ Ξανά';\n  t.push(setTimeout(()=>{c.classList.add('on');const g=$$('.tok.go',rx);g[0].style.transform='translate(40px,-60px)';g[1].style.transform='translate(-40px,-60px)';g.forEach(x=>x.style.opacity='0');},1700));\n  t.push(setTimeout(()=>{p.classList.add('on');n.classList.add('on');},2500));};\n})();\n\n/* ---------- 8.1 triglyceride ---------- */\n(function(){const host=$('#tgRows');const ys=[100,240,380];\n function zig(y,kink){let pts='256,'+y;let x=256;for(let j=0;j<16;j++){let yy;if(kink&&j>=8){x+=32;yy=y+(j-7)*16+(j%2?10:-10);}else{x+=36;yy=y+(j%2?14:-14);}pts+=' '+x+','+yy;}return pts;}\n ys.forEach((y,i)=>{\n  host.appendChild(el('line',{x1:90,y1:y,x2:250,y2:y,stroke:'var(--bond)','stroke-width':10}));\n  host.appendChild(el('line',{x1:250,y1:y,x2:250,y2:y-62,stroke:'var(--atom-o)','stroke-width':7}));\n  host.appendChild(el('line',{x1:262,y1:y,x2:262,y2:y-62,stroke:'var(--atom-o)','stroke-width':7}));\n  const s=el('polyline',{points:zig(y,false),fill:'none',stroke:'var(--acid)','stroke-width':10,'stroke-linejoin':'round','stroke-linecap':'round'});s.style.transition='opacity .6s';host.appendChild(s);\n  if(i===2){const k=el('polyline',{points:zig(y,true),fill:'none',stroke:'var(--acid)','stroke-width':10,'stroke-linejoin':'round','stroke-linecap':'round',id:'tgKink',opacity:0});k.style.transition='opacity .6s';host.appendChild(k);s.id='tgStraight';}\n  host.appendChild(el('circle',{cx:90,cy:y,r:30,fill:'var(--alc)'}));\n  host.appendChild(el('circle',{cx:172,cy:y,r:24,fill:'var(--atom-o)'}));\n  host.appendChild(el('circle',{cx:256,cy:y,r:22,fill:'var(--atom-c)'}));\n  host.appendChild(el('circle',{cx:256,cy:y-64,r:20,fill:'var(--atom-o)'}));\n });\n $$('#fatPick button').forEach(b=>b.onclick=()=>{$$('#fatPick button').forEach(x=>x.setAttribute('aria-pressed',x===b));const u=b.dataset.k==='uns';\n  $('#tgKink').setAttribute('opacity',u?1:0);$('#tgStraight').setAttribute('opacity',u?0:1);$('#tgNote').setAttribute('opacity',u?1:0);});\n})();\n\n/* ---------- 8.2 micelle ---------- */\n(function(){const host=$('#micMols');const N=16;const mols=[];\n for(let k=0;k<N;k++){const g=el('g',{});let pts='0,0';for(let j=1;j<=6;j++)pts+=' '+(j*15)+','+(j%2?8:-8);\n  g.appendChild(el('polyline',{points:pts,fill:'none',stroke:'var(--acid)','stroke-width':7,'stroke-linejoin':'round'}));\n  g.appendChild(el('circle',{cx:108,cy:0,r:17,fill:'var(--alc)'}));\n  g.style.transition='transform 1.4s cubic-bezier(.3,.8,.3,1)';g.style.transitionDelay=(k*40)+'ms';host.appendChild(g);mols.push(g);}\n function scatter(){mols.forEach(g=>{const x=40+Math.random()*360,y=40+Math.random()*360;let ok=Math.hypot(x+50-260,y-260)>150;const X=ok?x:(x<260?x-140:x+60);g.style.transform='translate('+Math.max(20,Math.min(400,X))+'px,'+y+'px) rotate('+(Math.random()*360|0)+'deg)';});\n  $('#micCap').textContent='Τα μόρια του σαπουνιού κολυμπάνε σκόρπια στο νερό.';}\n function gather(){mols.forEach((g,k)=>{const t=2*Math.PI*k/N, d=t*180/Math.PI;g.style.transform='translate('+(260+98*Math.cos(t))+'px,'+(260+98*Math.sin(t))+'px) rotate('+d+'deg)';});\n  $('#micCap').textContent='Οι ουρές «βουτάνε» στη σταγόνα λίπους, οι κεφαλές μένουν στο νερό: σχηματίζεται μικκύλιο, και το λίπος φεύγει με το ξέβγαλμα.';}\n scatter();$('#micGo').onclick=gather;$('#micReset').onclick=scatter;\n})();\n\n/* ---------- games: tabs ---------- */\nfunction openGame(p){$$('.games-nav button').forEach(x=>x.setAttribute('aria-selected',x.dataset.p===p));$$('.panel').forEach(x=>x.classList.toggle('on',x.id==='p-'+p));}\n$$('.games-nav button').forEach(b=>b.onclick=()=>openGame(b.dataset.p));\n$$('[data-game]').forEach(a=>a.addEventListener('click',()=>openGame(a.dataset.game)));\n\n/* ---------- quiz ---------- */\nconst TOP={eth:{n:'Αιθέρες: δομή & ονόματα',h:'#s-6-2'},iso:{n:'Ισομέρεια & ιδιότητες',h:'#s-6-3'},es:{n:'Εστέρες: ονόματα & τύποι',h:'#s-7-2'},rx:{n:'Εστεροποίηση & υδρόλυση',h:'#esteropoiisi'},fat:{n:'Λίπη, έλαια, σαπούνια',h:'#s-8-1'}};\nconst Q=[\n {t:'eth',q:'Ποια είναι η χαρακτηριστική ομάδα των αιθέρων;',a:'–C–O–C– (O ανάμεσα σε δύο C)',w:['–OH','–COO–','–COOH'],e:'Στους αιθέρες ένα οξυγόνο ενώνει δύο αλκύλια: R–O–R′. Το –OH ανήκει στις αλκοόλες και το –COO– στους εστέρες.',h:'#s-6-1'},\n {t:'eth',q:'Πώς ονομάζεται η ένωση <span class=\"f\">CH₃–O–CH₂CH₃</span>;',a:'αιθυλομεθυλαιθέρας',w:['μεθυλαιθυλεστέρας','αιθανικός μεθυλεστέρας','προπανόλη'],e:'Τα αλκύλια μπαίνουν με αλφαβητική σειρά (αιθυλ- πριν από μεθυλ-) και ακολουθεί η λέξη «αιθέρας». Κατά IUPAC: μεθοξυαιθάνιο.',h:'#s-6-2'},\n {t:'eth',q:'Η ένωση <span class=\"f\">CH₃CH₂–O–CH₂CH₃</span> κατά IUPAC λέγεται:',a:'αιθοξυαιθάνιο',w:['μεθοξυπροπάνιο','βουτανόλη','αιθανικός αιθυλεστέρας'],e:'Το ένα αιθύλιο μαζί με το O γίνεται «αιθοξυ-» και το άλλο είναι το «αιθάνιο». Το κοινό του όνομα είναι διαιθυλαιθέρας.',h:'#s-6-2'},\n {t:'iso',q:'Ο διμεθυλαιθέρας <span class=\"f\">CH₃OCH₃</span> είναι ισομερής με:',a:'την αιθανόλη',w:['τη μεθανόλη','το αιθανικό οξύ','το αιθάνιο'],e:'Και οι δύο έχουν τύπο C₂H₆O. Αλκοόλες και αιθέρες με ίδιο αριθμό C είναι ισομερή ομόλογης σειράς (C<sub>ν</sub>H<sub>2ν+2</sub>O).',h:'#s-6-3'},\n {t:'iso',q:'Γιατί η αιθανόλη βράζει στους 78 °C ενώ ο διμεθυλαιθέρας στους −24 °C;',a:'Η αιθανόλη σχηματίζει δεσμούς υδρογόνου',w:['Η αιθανόλη έχει μεγαλύτερη μοριακή μάζα','Η αιθανόλη έχει περισσότερα άτομα C','Ο αιθέρας είναι ιοντική ένωση'],e:'Έχουν ίδιο τύπο, άρα ίδια μάζα. Η διαφορά είναι το –OH: τα μόρια της αλκοόλης ενώνονται με δεσμούς υδρογόνου, ενώ ο αιθέρας δεν έχει H πάνω στο O.',h:'#s-6-3'},\n {t:'iso',q:'Πόσοι άκυκλοι αιθέρες έχουν μοριακό τύπο <span class=\"f\">C₄H₁₀O</span>;',a:'3',w:['2','4','7'],e:'Το 1+3 δίνει 1-μεθοξυπροπάνιο και 2-μεθοξυπροπάνιο, και το 2+2 αιθοξυαιθάνιο. Το 7 είναι όλα τα ισομερή μαζί με τις 4 αλκοόλες.',h:'#s-6-4'},\n {t:'es',q:'Πώς ονομάζεται ο εστέρας <span class=\"f\">CH₃COOCH₂CH₃</span>;',a:'αιθανικός αιθυλεστέρας',w:['αιθυλικός αιθανεστέρας','προπανικός μεθυλεστέρας','βουτανικό οξύ'],e:'Το CH₃COO– έχει 2 C και προέρχεται από το αιθανικό οξύ. Το –CH₂CH₃ είναι αιθύλιο από την αιθανόλη. Πρώτα το οξύ, μετά το αλκύλιο.',h:'#s-7-2'},\n {t:'es',q:'Πώς ονομάζεται ο εστέρας <span class=\"f\">HCOOCH₃</span>;',a:'μεθανικός μεθυλεστέρας',w:['αιθανικός μεθυλεστέρας','διμεθυλαιθέρας','αιθανικό οξύ'],e:'Το HCOO– προέρχεται από το μεθανικό οξύ, HCOOH, με 1 C. Είναι ο απλούστερος εστέρας, γι’ αυτό ν ≥ 2.',h:'#s-7-1'},\n {t:'es',q:'Ποιος είναι ο τύπος του <b>προπανικού μεθυλεστέρα</b>;',a:'CH₃CH₂COOCH₃',w:['CH₃COOCH₂CH₃','HCOOCH₂CH₂CH₃','CH₃OCH₂CH₂CH₃'],e:'«Προπανικός» σημαίνει 3 C στο κομμάτι του οξέος, μαζί με τον C του –COO–: CH₃CH₂COO–. «Μεθυλ» σημαίνει –CH₃ μετά το O.',h:'#s-7-2'},\n {t:'rx',q:'Συμπλήρωσε: <span class=\"f\">CH₃COOH + CH₃OH ⇌ ;</span>',a:'CH₃COOCH₃ + H₂O',w:['CH₃OCH₃ + CO₂','CH₃COONa + H₂O','CH₃CH₂COOH'],e:'Εστεροποίηση: το RCO– του οξέος ενώνεται με το –OCH₃ της αλκοόλης και βγαίνει ένα μόριο νερού.',h:'#esteropoiisi'},\n {t:'rx',q:'Ποιος είναι ο καταλύτης της εστεροποίησης;',a:'πυκνό H₂SO₄',w:['NaOH','Ni','φως (hv)'],e:'Χρησιμοποιούμε πυκνό θειικό οξύ και θέρμανση. Το NaOH κάνει την αντίστροφη δουλειά: σπάει τους εστέρες.',h:'#esteropoiisi'},\n {t:'rx',q:'Η εστεροποίηση είναι αντίδραση:',a:'αμφίδρομη (⇌)',w:['μονόδρομη (→)','εξουδετέρωσης','καύσης'],e:'Καταλήγει σε χημική ισορροπία, γι’ αυτό γράφουμε πάντα διπλό βέλος ⇌.',h:'#esteropoiisi'},\n {t:'rx',q:'Τι παίρνουμε όταν ένας εστέρας αντιδρά με NaOH (σαπωνοποίηση);',a:'άλας του οξέος + αλκοόλη',w:['οξύ + αλκοόλη','αιθέρα + νερό','αλκάνιο + CO₂'],e:'RCOOR′ + NaOH → RCOONa + R′OH. Είναι μονόδρομη. Οξύ και αλκοόλη δίνει η όξινη υδρόλυση, που είναι αμφίδρομη.',h:'#s-7-4'},\n {t:'fat',q:'Τα λίπη και τα έλαια είναι εστέρες:',a:'της γλυκερίνης με λιπαρά οξέα',w:['της αιθανόλης με οξικό οξύ','της μεθανόλης με λιπαρά οξέα','του νατρίου με γλυκερίνη'],e:'Η γλυκερίνη έχει 3 –OH, οπότε δένει 3 λιπαρά οξέα: σχηματίζει τριγλυκερίδιο.',h:'#s-8-1'},\n {t:'fat',q:'Τι είναι χημικά το σαπούνι;',a:'άλας νατρίου ή καλίου λιπαρού οξέος',w:['εστέρας της γλυκερίνης','αιθέρας','καθαρό λιπαρό οξύ'],e:'Λίπος + NaOH → σαπούνι (RCOONa) + γλυκερίνη. Η μακριά ουρά πιάνει το λίπος και η κεφαλή –COO⁻ το νερό.',h:'#s-8-2'}\n];\nlet order,qi,score,byT;\nfunction startQuiz(){order=shuffle(Q);qi=0;score=0;byT={};for(const k in TOP)byT[k]={ok:0,n:0};$('#qfb').innerHTML='';renderQ();}\nfunction renderQ(){const q=order[qi];\n $('#qnum').textContent='Ερώτηση '+(qi+1)+' από '+order.length;$('#qscore').textContent='Σωστές: '+score;$('#qbar').style.width=(qi/order.length*100)+'%';\n const opts=shuffle([q.a].concat(q.w));\n $('#qbody').innerHTML='<span class=\"tag\">'+TOP[q.t].n.toUpperCase()+'</span><p class=\"q\">'+q.q+'</p><div class=\"opts\">'+opts.map((o,i)=>'<button class=\"opt\" data-v=\"'+o+'\"><b>'+'ΑΒΓΔ'[i]+'</b><span>'+o+'</span></button>').join('')+'</div>';\n $('#qfb').innerHTML='';$('#qnext').hidden=true;$$('#qbody .opt').forEach(b=>b.onclick=()=>answer(b,q));}\nfunction answer(b,q){const ok=b.dataset.v===q.a;\n $$('#qbody .opt').forEach(x=>{x.disabled=true;if(x.dataset.v===q.a)x.classList.add('ok');});if(!ok)b.classList.add('bad','shake');\n byT[q.t].n++;if(ok){score++;byT[q.t].ok++;}$('#qscore').textContent='Σωστές: '+score;\n $('#qfb').innerHTML='<div class=\"fb'+(ok?'':' bad')+'\"><strong>'+(ok?'✓ Σωστά!':'✗ Όχι ακριβώς. Σωστό: '+q.a)+'</strong>'+q.e+(ok?'':' <a href=\"'+q.h+'\">Γύρνα στην ενότητα →</a>')+'</div>';\n const n=$('#qnext');n.hidden=false;n.textContent=qi===order.length-1?'Δες το αποτέλεσμα →':'Επόμενη →';}\nfunction nextQ(){qi++;qi<order.length?renderQ():endQuiz();}\n$('#qnext').onclick=()=>{if(qi>=order.length){startQuiz();return;}nextQ();};\nfunction endQuiz(){$('#qbar').style.width='100%';const pct=Math.round(score/order.length*100);\n const best=Math.max(store.get('organiki2-best',0),score);store.set('organiki2-best',best);\n const msg=pct>=90?'Εξαιρετικά! Το κεφάλαιο το έχεις. 🏆':pct>=70?'Πολύ καλά! Λίγο φρεσκάρισμα σε ό,τι φαίνεται πορτοκαλί. 💪':pct>=50?'Καλή αρχή. Ξαναδές τις ενότητες που προτείνονται. 📚':'Θέλει μια επανάληψη και μετά ξανά. Θα το πιάσεις! 🔁';\n const weak=Object.keys(TOP).filter(k=>byT[k].n&&byT[k].ok/byT[k].n<.7);\n $('#qnum').textContent='Τέλος!';$('#qscore').textContent='Καλύτερο σκορ: '+best+'/'+order.length;\n $('#qbody').innerHTML='<div class=\"score\">'+score+'/'+order.length+'</div><p class=\"q\">'+msg+'</p>'+Object.keys(TOP).map(k=>{const t=byT[k],p=t.n?Math.round(t.ok/t.n*100):0;return '<div class=\"trow\"><a href=\"'+TOP[k].h+'\" style=\"color:var(--ink);font-weight:600;text-decoration:none\">'+TOP[k].n+'</a><div class=\"pbar\"><i data-w=\"'+p+'\" style=\"background:'+(p>=70?'var(--accent)':'var(--acid)')+'\"></i></div><b style=\"text-align:right\">'+t.ok+'/'+t.n+'</b></div>';}).join('')+\n  (weak.length?'<div class=\"rule w\"><b>Τι να ξαναδιαβάσεις:</b><br>'+weak.map(k=>'<a href=\"'+TOP[k].h+'\">'+TOP[k].n+' →</a>').join('<br>')+'</div>':'');\n $('#qfb').innerHTML='';const n=$('#qnext');n.hidden=false;n.textContent='Ξανά από την αρχή ↺';qi=order.length;\n setTimeout(()=>$$('#qbody .trow i').forEach(i=>i.style.width=i.dataset.w+'%'),60);}\nstartQuiz();\n\n/* ---------- sort game ---------- */\nconst CATS=[['alc','Αλκοόλη','R–OH'],['eth','Αιθέρας','R–O–R′'],['acid','Οξύ','R–COOH'],['est','Εστέρας','R–COO–R′']];\nconst SF=[['CH₃CH₂OH','alc'],['CH₃OCH₃','eth'],['CH₃COOH','acid'],['CH₃COOCH₃','est'],['HCOOH','acid'],['HCOOCH₂CH₃','est'],['CH₃CH₂OCH₂CH₃','eth'],['CH₃CH(OH)CH₃','alc'],['CH₃CH₂COOH','acid'],['CH₃CH₂COOCH₃','est'],['CH₃OCH₂CH₂CH₃','eth'],['CH₃CH₂CH₂OH','alc'],['(CH₃)₃COH','alc'],['CH₃CH₂CH₂COOCH₂CH₃','est'],['CH₃CH₂CH₂COOH','acid'],['CH₃CH₂OCH₃','eth']];\nconst WHY={alc:'Έχει –OH στο άκρο: αλκοόλη.',eth:'Το O είναι ανάμεσα σε δύο άτομα C και δεν έχει H: αιθέρας.',acid:'Τελειώνει σε –COOH: καρβοξυλικό οξύ.',est:'Έχει –COO– ανάμεσα σε δύο κομμάτια: εστέρας.'};\nlet so,si,streak,sok;\nfunction startSort(){so=shuffle(SF).slice(0,10);si=0;streak=0;sok=0;$('#sbest').textContent=store.get('organiki2-streak',0);renderS();}\nfunction renderS(){const f=so[si][0];$('#snum').textContent=(si+1)+' από '+so.length;$('#sbar').style.width=(si/so.length*100)+'%';\n const sf=$('#sform');sf.textContent=f;sf.style.animation='none';void sf.offsetWidth;sf.style.animation='rise .3s';\n $('#scats').innerHTML=CATS.map(c=>'<button class=\"cat\" data-k=\"'+c[0]+'\">'+c[1]+'<small>'+c[2]+'</small></button>').join('');\n $('#sfb').innerHTML='';$('#snext').hidden=true;$('#sstreak').textContent=streak;$$('#scats .cat').forEach(b=>b.onclick=()=>sAns(b));}\nfunction sAns(b){const k=so[si][1],ok=b.dataset.k===k;\n $$('#scats .cat').forEach(x=>{x.disabled=true;if(x.dataset.k===k)x.classList.add('ok');});\n if(ok){streak++;sok++;if(streak>store.get('organiki2-streak',0)){store.set('organiki2-streak',streak);$('#sbest').textContent=streak;}}else{streak=0;b.classList.add('bad','shake');}\n $('#sstreak').textContent=streak;$('#sfb').innerHTML='<div class=\"fb'+(ok?'':' bad')+'\"><strong>'+(ok?'✓ Σωστά!':'✗ Όχι.')+'</strong>'+WHY[k]+'</div>';\n const n=$('#snext');n.hidden=false;n.textContent=si===so.length-1?'Τέλος →':'Επόμενο →';}\n$('#snext').onclick=()=>{if(si>=so.length){startSort();return;}si++;if(si<so.length){renderS();return;}\n $('#sbar').style.width='100%';$('#sform').textContent=sok+'/'+so.length+' σωστά';$('#scats').innerHTML='';\n $('#sfb').innerHTML=sok>=8?'<div class=\"fb\"><strong>Μπράβο!</strong>Αναγνωρίζεις τις ομάδες με την πρώτη ματιά.</div>':'<div class=\"fb bad\"><strong>Ξανά;</strong>Δες πρώτα τις ενότητες <a href=\"#s-6-1\">6.1</a> και <a href=\"#s-7-1\">7.1</a>.</div>';\n $('#snext').textContent='Νέος γύρος ↺';};\nstartSort();\n\n/* ---------- build an ester ---------- */\n(function(){\n const AC=[{n:'μεθανικό',adj:'μεθανικός',r:'H',c:1},{n:'αιθανικό',adj:'αιθανικός',r:'CH₃',c:2},{n:'προπανικό',adj:'προπανικός',r:'CH₃CH₂',c:3},{n:'βουτανικό',adj:'βουτανικός',r:'CH₃CH₂CH₂',c:4}];\n const AL=[{n:'μεθανόλη',p:'μεθυλ',r:'CH₃',c:1},{n:'αιθανόλη',p:'αιθυλ',r:'CH₂CH₃',c:2},{n:'1-προπανόλη',p:'προπυλ',r:'CH₂CH₂CH₃',c:3},{n:'1-πεντανόλη',p:'πεντυλ',r:'(CH₂)₄CH₃',c:5},{n:'1-οκτανόλη',p:'οκτυλ',r:'(CH₂)₇CH₃',c:8}];\n const SM={'βουτανικός αιθυλ':'🍍 Ανανάς','αιθανικός πεντυλ':'🍌 Μπανάνα','αιθανικός οκτυλ':'🍊 Πορτοκάλι','βουτανικός μεθυλ':'🍎 Μήλο','βουτανικός πεντυλ':'🍑 Βερίκοκο','αιθανικός αιθυλ':'💅 Φρουτώδης: διαλύτης στο ασετόν νυχιών'};\n let A=null,L=null;\n $('#bAcid').innerHTML=AC.map((a,i)=>'<button aria-pressed=\"false\" data-i=\"'+i+'\">'+a.n+'</button>').join('');\n $('#bAlc').innerHTML=AL.map((a,i)=>'<button aria-pressed=\"false\" data-i=\"'+i+'\">'+a.n+'</button>').join('');\n $$('#bAcid button').forEach(b=>b.onclick=()=>{A=AC[b.dataset.i];$$('#bAcid button').forEach(x=>x.setAttribute('aria-pressed',x===b));build();});\n $$('#bAlc button').forEach(b=>b.onclick=()=>{L=AL[b.dataset.i];$$('#bAlc button').forEach(x=>x.setAttribute('aria-pressed',x===b));build();});\n function build(){$('#bRes').innerHTML='';\n  if(!A||!L){$('#bEq').innerHTML='<span class=\"muted\" style=\"font-family:var(--f-body);font-weight:500;font-size:18px\">Διάλεξε και '+(A?'αλκοόλη':'οξύ')+' 👆</span>';$('#bGuess').innerHTML='';return;}\n  const name=A.adj+' '+L.p+'εστέρας';\n  let swap=L.p.replace(/υλ$/,'ανικός')+' '+A.adj.replace(/ανικός$/,'υλ')+'εστέρας';\n  if(swap===name)swap=A.adj+' '+AL.find(x=>x.c!==L.c).p+'εστέρας';\n  const opts=shuffle([name,swap,A.adj+' '+L.p+'αιθέρας']);\n  $('#bEq').innerHTML='<span class=\"tok a\">'+A.r+'CO</span><span class=\"tok go\">OH</span><span class=\"op\">+</span><span class=\"tok go\">H</span><span class=\"tok l\">O'+L.r+'</span><span class=\"arrow2\" style=\"font-size:1.3em\">⇌</span><span class=\"tok a\" style=\"animation:rise .5s .2s both\">'+A.r+'COO</span><span class=\"tok l\" style=\"margin-left:-14px;animation:rise .5s .2s both\">'+L.r+'</span><span class=\"op\">+</span><span class=\"tok w\" style=\"animation:pop .6s .5s both\">H₂O</span>';\n  $('#bGuess').innerHTML='<p style=\"font-weight:600;font-size:19px\">Πριν δεις τη λύση: πώς λέγεται ο εστέρας που φτιάχτηκε;</p><div class=\"opts\">'+opts.map((o,i)=>'<button class=\"opt\" data-v=\"'+o+'\"><b>'+'ΑΒΓ'[i]+'</b><span>'+o+'</span></button>').join('')+'</div>';\n  $$('#bGuess .opt').forEach(b=>b.onclick=()=>{const ok=b.dataset.v===name;$$('#bGuess .opt').forEach(x=>{x.disabled=true;if(x.dataset.v===name)x.classList.add('ok');});if(!ok)b.classList.add('bad','shake');res(name,ok);});}\n function res(name,ok){const n=A.c+L.c;const it=[['Αποτέλεσμα',ok?'✓ Το βρήκες!':'✗ Το σωστό είναι το πράσινο'],['Όνομα',name],['Τύπος',A.r+'COO'+L.r],['Μοριακός τύπος','C'+sub(n)+'H'+sub(2*n)+'O₂ (ν = '+n+')'],['Μυρίζει…',SM[A.adj+' '+L.p]||'Όχι γνωστό άρωμα, αλλά οι μικροί εστέρες μυρίζουν συνήθως φρουτώδεις']];\n  $('#bRes').innerHTML=it.map((x,i)=>'<div style=\"animation-delay:'+(i*90)+'ms\"><span class=\"lbl\">'+x[0]+'</span><div class=\"v\">'+x[1]+'</div></div>').join('');}\n})();\n\n/* ---------- study marks (shared format with the other Mixalis lessons) ---------- */\n(function(){\nconst SK='mixalis-study-v1',TK='mixalis-study-total-v1',LS='organiki2';\nconst rd=k=>{try{const o=JSON.parse(localStorage.getItem(k)||'{}');return o&&typeof o==='object'?o:{};}catch(e){return {};}};\nconst wr=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v));}catch(e){}};\nconst U=[];\n$$('.sec').forEach(sec=>{const h=$('h2',sec),sn=h&&$('.sn',h);if(!sn||!sec.id)return;const num=sn.textContent.trim();\n const title=num+' '+h.textContent.trim().slice(num.length).trim();\n const bar=document.createElement('div');bar.className='stmark';\n bar.innerHTML='<span>Πώς πήγε;</span><button type=\"button\" data-s=\"done\" aria-pressed=\"false\">✓ Τελείωσα</button><button type=\"button\" data-s=\"again\" aria-pressed=\"false\">★ Να το ξαναδώ</button>';\n sec.appendChild(bar);const u={id:sec.id,title,bar};U.push(u);\n $$('button',bar).forEach(b=>b.onclick=()=>{const d=rd(SK);const m=d[LS]=d[LS]||{};const cur=m[u.id]&&m[u.id].s;\n  if(cur===b.dataset.s)delete m[u.id];else m[u.id]={s:b.dataset.s,t:'Οργανική 2 · '+title,h:'/mixalis/organiki2#'+u.id,at:Date.now()};wr(SK,d);paint();});});\nconst T=rd(TK);T[LS]=U.length;wr(TK,T);\nconst fab=document.createElement('button');fab.id='stFab';fab.type='button';document.body.appendChild(fab);\nfab.onclick=()=>{const m=rd(SK)[LS]||{};const next=U.find(u=>!(m[u.id]&&m[u.id].s==='done'));if(next)document.getElementById(next.id).scrollIntoView({behavior:'smooth'});};\nfunction paint(){const m=rd(SK)[LS]||{};let done=0,again=0;U.forEach(u=>{const s=m[u.id]&&m[u.id].s;$$('button',u.bar).forEach(b=>b.setAttribute('aria-pressed',b.dataset.s===s));if(s==='done')done++;if(s==='again')again++;});\n fab.textContent='✓ '+done+'/'+U.length+' · ★ '+again;fab.title='Πήγαινε στην επόμενη ενότητα που δεν τελείωσες';}\npaint();\n})();\n\n})();\n</script>\n</body>\n</html>\n";
